    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    n = min(sep, w - sep - 1)

    def most_common(part):
        counts = {}
        for row in part:
            for x in row:
                counts[x] = counts.get(x, 0) + 1
        return max(counts, key=counts.get)

    lb, rb = most_common(left), most_common(right)
    # Use the foreground color common to the two panels as the output fill.
    lf = next((x for row in left for x in row if x != lb), 4)
    rf = next((x for row in right for x in row if x != rb), lf)
    fill = lf if lf == rf else rf
    out = [[fill] * n for _ in range(h)]
    for r in range(h):
        for c in range(n):
            if left[r][c] != lb and right[r][c] != rb:
                out[r][c] = 3
    return out
